INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('site.name', 'ru', 'Сюзана Тевдорадзе', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('site.role', 'ru', 'AI / Technical Product Lead', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('site.description', 'ru', 'Продуктовая стратегия для AI- и дата-продуктов: проверить спрос, цену и экономику до того, как потрачены деньги.', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('nav.home', 'ru', 'Главная', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('nav.pricing', 'ru', 'Цены', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('nav.about', 'ru', 'Обо мне', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('nav.contact', 'ru', 'Контакты', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('hero.kicker', 'ru', 'AI / Technical Product Lead', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('hero.title', 'ru', 'Понять, что стоит строить — до того как потрачены деньги', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('hero.lead', 'ru', 'Меня зовут Сюзана Тевдорадзе. Я продакт-лид с техническим бэкграундом: веду AI- и дата-продукты от стратегии до запуска, консультирую и подключаюсь к командам.', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('hero.cta', 'ru', 'Бесплатный разговор, 20–40 минут', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('hero.note', 'ru', 'Без питча и слайдов. Если по делу хватит одного разговора — этим и ограничимся.', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('problems.title', 'ru', 'С чем ко мне приходят', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('problems.items', 'ru', '- Есть идея AI-продукта — и хочется понять, купит ли её кто-нибудь, **до** найма разработчиков.
- Продукт строится или запущен, но непонятно, за что готовы платить и сходится ли экономика, если честно посчитать токены и ручные шаги.
- AI-фича «почти работает» который месяц. Деньги уходят, а решение «докручивать или остановиться» никто не принимает.
- Продакта в команде нет: стратегию, бэклог и разговоры с пользователями тянет фаундер.', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('formats.title', 'ru', 'Три формата работы', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('formats.inside_label', 'ru', 'Что внутри', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('formats.audit.title', 'ru', 'Проверка «строить или нет»', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('formats.audit.duration', 'ru', '2–3 недели, фиксированный объём', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('formats.audit.price', 'ru', 'от €3 500', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('formats.audit.body', 'ru', 'Для идеи или раннего продукта — на развилке перед большими тратами. На выходе письменный вердикт: **строить / подождать / переделать замысел**, с источником под каждым выводом и план самого дешёвого следующего теста. Иногда вердикт — «не строить». Это решение, принятое до потраченных денег.', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('formats.audit.inside', 'ru', '- Разбор отзывов на конкурентов и на то, чем люди обходятся сейчас
- 5–8 интервью с вашей аудиторией — включая тех, кто не купил
- Карта рисков: какое предположение самое опасное
- Экономика на одну страницу: конверсия, стоимость клиента, стоимость эксплуатации на пользователя', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('formats.discovery.title', 'ru', 'Discovery-спринт', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('formats.discovery.duration', 'ru', '4–6 недель, до плана запуска', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('formats.discovery.price', 'ru', 'от €7 000', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('formats.discovery.body', 'ru', 'Для тех, кто решил строить и хочет проверенный план, а не список фич. Всё из проверки — глубже, плюс позиционирование, тест цены на реальном трафике, скоуп MVP и роадмап на 6–12 месяцев.', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('formats.discovery.inside', 'ru', '- Позиционирование: с чем вас на самом деле сравнивает покупатель
- Тест цены: страница с настоящей ценой и заранее записанным порогом остановки
- Скоуп MVP: что режем, чтобы проверить главный риск
- Приоритизированный роадмап на 6–12 месяцев', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('formats.fractional.title', 'ru', 'AI / Technical Product Lead в вашей команде', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('formats.fractional.duration', 'ru', '1–2 дня в неделю, первый месяц — пробный', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('formats.fractional.price', 'ru', 'от €3 000 / мес', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('formats.fractional.body', 'ru', 'Для команд, где продукт живёт, а владельца у него нет. Беру стратегию и роадмап, еженедельное discovery, метрики и экономику, разговоры со стейкхолдерами — и помогаю нанять постоянного продакта. Хорошая фракционная работа заканчивается тем, что я становлюсь не нужна.', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('formats.fractional.inside', 'ru', '- Стратегия и роадмап
- Еженедельное discovery и метрики
- Экономика решений, включая стоимость AI
- Путь от прототипа до production', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('formats.footnote', 'ru', 'Разовая консультация (€150) и почасовая работа (от €100/час) — на странице [«Цены»](/ru/pricing).', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('process.title', 'ru', 'Как это устроено', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('process.steps', 'ru', '- Бесплатный разговор, 20–40 минут.
- Письмо с фиксированными объёмом, сроком и ценой. Никаких «посмотрим по ходу».
- Работа с коротким апдейтом раз в неделю.
- Финальная сессия и письменный отчёт.', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('process.principles', 'ru', '- Порог остановки записываем до старта: что считать неудачей, формулируется заранее.
- Я не продаю часы — я продаю ответ на вопрос и следующий шаг.
- Каждый вывод проверяем: цитата из отзыва, запись интервью, цифра с источником и датой. Если результат нельзя проверить — это не результат.', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('fit.title', 'ru', 'Кому подойдёт — и кому нет', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('fit.body', 'ru', 'Чаще всего — фаундерам до запуска и командам, у которых AI- или дата-продукт не сходится: с деньгами, метриками или ожиданиями. Отрасль значит меньше, чем кажется: метод один — проверить спрос, цену и экономику до кода.', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('fit.not', 'ru', 'Я не подойду, если нужен исполнитель, который молча пишет фичи по списку, или агентство на разработку. Моя работа — до и вокруг разработки: что строить, почём и зачем.', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('cta.title', 'ru', 'Разобрать ваш продукт?', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('cta.body', 'ru', 'Напишите или забронируйте бесплатные 20–40 минут.', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('pricing.title', 'ru', 'Цены', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('pricing.intro', 'ru', 'Все цены — ориентиры «от»: точную цену фиксируем письменно после бесплатного знакомства, вместе с объёмом и сроком. Дальше она не меняется.', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('pricing.columns', 'ru', 'Формат | Срок | Цена', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('pricing.rows', 'ru', 'Знакомство | 20–40 минут | бесплатно
Консультация с письменным резюме | 60–90 минут | €150
Почасовая работа | по договорённости; первая задача от 2 часов | от €100 / час
Проверка «строить или нет» | 2–3 недели, фикс-скоуп | от €3 500
Discovery-спринт | 4–6 недель | от €7 000
AI / Technical Product Lead в команде | 1 день в неделю; первый месяц пробный | от €3 000 / мес
 | 2 дня в неделю | от €5 500 / мес
Фултайм-контракт | от 3 месяцев | по запросу', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('pricing.note', 'ru', 'Знакомство бесплатно один раз: дальше любой разбор — это работа, и она оплачивается. Суммы — по инвойсу, до налогов.', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('about.title', 'ru', 'Обо мне', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('about.bio', 'ru', 'Технический продакт-лид в AI- и дата-продуктах. Веду продукт от стратегии до запуска: руковожу командой, вывожу AI-функции в production, считаю экономику решений — включая стоимость моделей — и снижаю затраты там, где они не создают ценности.

Моя любимая часть работы — понять, что стоит строить, до того как потрачены деньги.', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('about.credentials', 'ru', 'AI / Technical Product Lead — стратегия, discovery, доставка', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('about.cv_label', 'ru', 'Скачать CV (PDF)', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('about.links_label', 'ru', 'Где я ещё', '1970-01-01T00:00:00Z');
