INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('contact.body', 'ru', 'Захотите разобрать свой продукт — забронируйте бесплатные 20–40 минут или напишите.', '1970-01-01T00:00:00Z');
