INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('footer.playful', 'ru', 'Балуюсь вайбкодингом — [здесь]({github}) — и этикой данных — [здесь]({channel}).', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('footer.channel_line', 'ru', 'Канал про этику данных и продуктовый анализ — думать до того, как строить.', '1970-01-01T00:00:00Z');
