INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('site.name', 'en', 'Syuzana Tevdoradze', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('site.role', 'en', 'AI / Technical Product Lead', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('site.description', 'en', 'Product strategy for AI and data products: test demand, price and economics before the money is spent.', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('nav.home', 'en', 'Home', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('nav.pricing', 'en', 'Pricing', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('nav.about', 'en', 'About', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('nav.contact', 'en', 'Contact', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('hero.kicker', 'en', 'AI / Technical Product Lead', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('hero.title', 'en', 'Know what''s worth building — before the money is spent', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('hero.lead', 'en', 'I''m Syuzana Tevdoradze, a product lead with a technical background. I take AI and data products from strategy to launch, consult, and join teams hands-on.', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('hero.cta', 'en', 'Free call, 20–40 minutes', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('hero.note', 'en', 'No pitch, no slides. If one conversation is enough, we stop there.', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('problems.title', 'en', 'What people come with', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('problems.items', 'en', '- An AI product idea — and the question of whether anyone will buy it, **before** hiring developers.
- A product in build or already live, but no clarity on what customers will pay for, or whether the economics hold once you count tokens and manual steps honestly.
- An AI feature that has "almost worked" for months. Money keeps going out; nobody decides whether to push on or stop.
- No product owner on the team: strategy, backlog and user conversations all land on the founder.', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('formats.title', 'en', 'Three ways to work', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('formats.inside_label', 'en', 'What''s inside', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('formats.audit.title', 'en', 'Build-or-not check', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('formats.audit.duration', 'en', '2–3 weeks, fixed scope', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('formats.audit.price', 'en', 'from €3,500', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('formats.audit.body', 'en', 'For an idea or an early product at the fork before big spending. You get a written verdict — **build / wait / rethink** — with a source behind every conclusion, and a plan for the cheapest next test. Sometimes the verdict is "don''t build". That''s a decision made before the money is spent.', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('formats.audit.inside', 'en', '- Review mining: competitors, and whatever people use today
- 5–8 interviews with your audience — including those who didn''t buy
- Risk map: which assumption is the most dangerous
- One-page economics: conversion, cost per customer, cost to serve per user', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('formats.discovery.title', 'en', 'Discovery sprint', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('formats.discovery.duration', 'en', '4–6 weeks, through to a launch plan', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('formats.discovery.price', 'en', 'from €7,000', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('formats.discovery.body', 'en', 'For those who''ve decided to build and want a tested plan, not a feature list. Everything in the check, deeper — plus positioning, a price test on real traffic, MVP scope and a 6–12-month roadmap.', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('formats.discovery.inside', 'en', '- Positioning: what buyers actually compare you with
- Price test: a real-price page with a stop threshold written down in advance
- MVP scope: what we cut to test the main risk
- Prioritised 6–12-month roadmap', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('formats.fractional.title', 'en', 'AI / Technical Product Lead on your team', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('formats.fractional.duration', 'en', '1–2 days a week; the first month is a trial', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('formats.fractional.price', 'en', 'from €3,000 / month', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('formats.fractional.body', 'en', 'For teams whose product is alive but has no owner. I take strategy and roadmap, weekly discovery, metrics and economics, stakeholder conversations — and help hire your permanent product lead. Fractional work done well ends with me no longer being needed.', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('formats.fractional.inside', 'en', '- Strategy and roadmap
- Weekly discovery and metrics
- Decision economics, including the cost of AI
- The path from prototype to production', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('formats.footnote', 'en', 'A one-off consultation (€150) and hourly work (from €100/hour) are on the [Pricing](/en/pricing) page.', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('process.title', 'en', 'How it works', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('process.steps', 'en', '- A free call, 20–40 minutes.
- A letter with fixed scope, timeline and price. No "let''s see as we go".
- The work, with a short weekly update.
- A final session and a written report.', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('process.principles', 'en', '- The stop threshold is written down before we start: what counts as failure is defined in advance.
- I don''t sell hours — I sell an answer to a question and the next step.
- Every conclusion is verifiable: a quote from a review, an interview recording, a number with a source and a date. If a result can''t be verified, it isn''t a result.', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('fit.title', 'en', 'Who it''s for — and who it isn''t', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('fit.body', 'en', 'Most often: founders before launch, and teams whose AI or data product doesn''t add up — on money, metrics or expectations. Industry matters less than it seems: the method is the same — test demand, price and economics before code.', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('fit.not', 'en', 'I''m not the right fit if you need someone to quietly ship features from a list, or a development agency. My work is before and around development: what to build, at what price, and why.', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('cta.title', 'en', 'Want to take your product apart?', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('cta.body', 'en', 'Write to me, or book a free 20–40 minutes.', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('pricing.title', 'en', 'Pricing', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('pricing.intro', 'en', 'All prices are "from" guides: the exact price is fixed in writing after the free intro call, together with scope and timeline. It doesn''t change after that.', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('pricing.columns', 'en', 'Format | Duration | Price', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('pricing.rows', 'en', 'Intro call | 20–40 minutes | free
Consultation with a written summary | 60–90 minutes | €150
Hourly work | by agreement; first task from 2 hours | from €100 / hour
Build-or-not check | 2–3 weeks, fixed scope | from €3,500
Discovery sprint | 4–6 weeks | from €7,000
AI / Technical Product Lead on your team | 1 day a week; first month is a trial | from €3,000 / month
 | 2 days a week | from €5,500 / month
Full-time contract | from 3 months | on request', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('pricing.note', 'en', 'The intro call is free once; after that any analysis is work, and work is paid. Amounts are invoiced before taxes.', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('about.title', 'en', 'About', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('about.bio', 'en', 'Technical product lead in AI and data products. I take a product from strategy to launch: lead the team, bring AI features to production, do the economics of decisions — including the cost of models — and cut spend where it creates no value.

My favourite part of the job is working out what''s worth building before the money is spent.', '1970-01-01T00:00:00Z');
INSERT OR IGNORE INTO content (key, lang, value, updated_at) VALUES ('about.credentials', 'en', 'AI / Technical Product Lead — strategy, discovery, delivery', '1970-01-01T00:00:00Z');
